{page==='course'&&<><HashRedirect base="/course/" slugs={list('courses').map(e=>e.slug)}/>{pageHero()}{list('affiliations').length>0&&<section className="trust"><div className="wrap">{list('affiliations').map(e=><div key={e.id} className="flex items-center gap-3">{e.image&&<img src={e.image} alt={e.alt||e.title} width={56} height={56} style={{objectFit:'contain'}}/>}<b>{e.title}</b></div>)}</div></section>}<section className="section"><div className="wrap"><div className="head"><div><div className="eyebrow">Find your next step</div><h2>A path for every aspiration.</h2></div><p>Choose a course to see its details, duration and how to enquire.</p></div>{list('courses').length?<div className="grid3">{list('courses').map(courseCard)}</div>:<div className="empty"><h3>Courses will appear here.</h3><p className="mt-4">Publish a course in the admin panel to list it here.</p></div>}</div></section>{instructors('Meet your Acharya')}{testimonialSection()}</>}
{page==='course-detail'&&selectedCourse&&<CoursePage e={selectedCourse} index={selectedCourseIndex} related={list('programs')} instructors={chosenInstructors(selectedCourse,list('instructors'))} onLead={enroll}/>}
{page==='program'&&<><HashRedirect base="/program/" slugs={list('programs').map(e=>e.slug)}/>{pageHero()}<section className="section"><div className="wrap"><div className="head"><div><div className="eyebrow">Daily practice</div><h2>Make practice a part of life.</h2></div><p>Choose a program to see its timings, how it is taught, and how to enquire.</p></div>{list('programs').length?<div className="grid3">{list('programs').map(programCard)}</div>:<div className="empty"><h3>Programs will appear here.</h3><p className="mt-4">Publish a program in the admin panel to list it here.</p></div>}</div></section>{instructors()}{testimonialSection()}</>}
{page==='instructor-detail'&&selectedInstructor&&<InstructorPage e={selectedInstructor} others={list('instructors').filter(x=>x.id!==selectedInstructor.id)} onLead={enroll}/>}
{page==='gallery-detail'&&selectedGallery&&<GalleryPage e={selectedGallery} related={list('gallery').filter(x=>x.id!==selectedGallery.id)}/>}
{page==='event-detail'&&selectedEvent&&<EventPage e={selectedEvent} related={splitEvents(list('events')).upcoming.filter(x=>x.id!==selectedEvent.id)} onLead={enroll}/>}
